from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    pieces = list(tiles[:n])
    if h <= 0 or w <= 0 or len(pieces) != n:
        return False

    areas = [a * b for a, b in pieces]
    if sum(areas) != h * w:
        return False

    full = (1 << (h * w)) - 1
    placements = []
    for a, b in pieces:
        options = set()
        for height, width in ((a, b), (b, a)):
            if height > h or width > w:
                continue
            for row in range(h - height + 1):
                for col in range(w - width + 1):
                    mask = 0
                    row_bits = (1 << width) - 1
                    for dy in range(height):
                        mask |= row_bits << ((row + dy) * w + col)
                    options.add(mask)
        placements.append(options)

    @lru_cache(maxsize=None)
    def search(covered: int, used: int) -> bool:
        if covered == full:
            return True

        # The unused pieces must cover precisely the remaining cells.
        remaining_area = h * w - covered.bit_count()
        area_left = sum(areas[i] for i in range(n) if not (used >> i) & 1)
        if remaining_area != area_left:
            return False

        first = next(i for i in range(h * w) if not (covered >> i) & 1)
        for i in range(n):
            if (used >> i) & 1:
                continue
            for mask in placements[i]:
                if (mask >> first) & 1 and not (mask & covered):
                    if search(covered | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

