from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play a card game. Each turn, a player plays a card and
    may take a table card with value no greater than the played card. The player
    who cannot move loses.
    """
    initial_takahashi = tuple(sorted(takahashi_cards))
    initial_aoki = tuple(sorted(aoki_cards))
    initial_table = tuple(sorted(table_cards))
    active = set()

    @lru_cache(maxsize=None)
    def winning(takahashi: Tuple[int, ...], aoki: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = takahashi if turn == 0 else aoki
        if not hand:
            return False

        state = (takahashi, aoki, table, turn)
        if state in active:
            # A repeated position can be maintained forever, so the player
            # who can force the repetition has a winning continuation.
            return False
        active.add(state)
        try:
            for played_index, played in enumerate(hand):
                hand_without_play = hand[:played_index] + hand[played_index + 1:]
                base_table = tuple(sorted(table + (played,)))

                # Playing without taking is always an available choice.
                if turn == 0:
                    if not winning(hand_without_play, aoki, base_table, 1):
                        return True
                elif not winning(takahashi, hand_without_play, base_table, 0):
                    return True

                # Taking an equal-valued card preserves the position's value
                # state but can still be strategically useful.
                for take_index, taken in enumerate(base_table):
                    if taken > played:
                        break
                    next_hand = tuple(sorted(hand_without_play + (taken,)))
                    next_table = base_table[:take_index] + base_table[take_index + 1:]
                    if turn == 0:
                        if not winning(next_hand, aoki, next_table, 1):
                            return True
                    elif not winning(takahashi, next_hand, next_table, 0):
                        return True
            return False
        finally:
            active.remove(state)

    return "Takahashi" if winning(initial_takahashi, initial_aoki, initial_table, 0) else "Aoki"

