def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count assignments whose result has at least k good substrings modulo 998244353.

    Deleting equal pairs and ABC triples reduces a substring to empty exactly when
    the three character counts have equal parity. In the quotient of F2^3 by
    {(0,0,0),(1,1,1)}, this means the prefix states at the two ends are equal.
    """
    mod = 998244353
    if k <= 0:
        return pow(3, s.count("?"), mod)
    if k > n * (n + 1) // 2:
        return 0

    # Represent the four quotient states as the elements of F2 x F2.
    # The letter steps are the three nonzero elements.
    step_for = {"A": 1, "B": 2, "C": 3}
    initial_counts = (1, 0, 0, 0)  # Include the prefix before the first character.
    dp = {(initial_counts, 0): 1}

    for ch in s:
        steps = (1, 2, 3) if ch == "?" else (step_for[ch],)
        nxt = {}
        for (counts, cur), ways in dp.items():
            for step in steps:
                dest = cur ^ step
                updated = list(counts)
                updated[dest] += 1
                key = (tuple(updated), dest)
                nxt[key] = (nxt.get(key, 0) + ways) % mod
        dp = nxt

    answer = 0
    for (counts, _), ways in dp.items():
        good = sum(c * (c - 1) // 2 for c in counts)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play a card game. Each turn, a player plays one card
    and may take a card from the table with a smaller value. The player who
    cannot make a move loses; both play optimally.
    """
    initial_takahashi = tuple(sorted(takahashi_cards))
    initial_aoki = tuple(sorted(aoki_cards))
    initial_table = tuple(sorted(table_cards))
    active = set()

    @lru_cache(maxsize=None)
    def winning(takahashi: Tuple[int, ...], aoki: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = takahashi if turn == 0 else aoki
        if not hand:
            return False

        state = (takahashi, aoki, table, turn)
        if state in active:
            return False
        active.add(state)
        try:
            for played_index, played in enumerate(hand):
                hand_without_play = hand[:played_index] + hand[played_index + 1:]
                base_table = tuple(sorted(table + (played,)))
                played_table_index = base_table.index(played)

                if turn == 0:
                    if not winning(hand_without_play, aoki, base_table, 1):
                        return True
                elif not winning(takahashi, hand_without_play, base_table, 0):
                    return True

                for take_index, taken in enumerate(base_table):
                    if taken > played:
                        break
                    if take_index == played_table_index:
                        continue
                    next_hand = tuple(sorted(hand_without_play + (taken,)))
                    next_table = base_table[:take_index] + base_table[take_index + 1:]
                    if turn == 0:
                        if not winning(next_hand, aoki, next_table, 1):
                            return True
                    elif not winning(takahashi, next_hand, next_table, 0):
                        return True
            return False
        finally:
            active.remove(state)

    return "Takahashi" if winning(initial_takahashi, initial_aoki, initial_table, 0) else "Aoki"

