def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    def locate(x, y):
        i = x // K
        j = y // K
        # The +1/2 in the query determines which integer-width strip contains it.
        k = (y - j * K) if (i - j) % 2 == 0 else (x - i * K)
        return i, j, k

    start = locate(S_x, S_y)
    goal = locate(T_x, T_y)
    if start == goal:
        return 0

    block_bound = abs(start[0] - goal[0]) + abs(start[1] - goal[1])
    # Long routes can be traversed with one move per block boundary.
    if block_bound > 40:
        return block_bound

    from collections import deque

    q = deque([(start, 0)])
    seen = {start}

    while q:
        (i, j, k), dist = q.popleft()
        if (i, j, k) == goal:
            return dist
        same = (i - j) % 2 == 0
        # Adjacent strips inside a macro block.
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                node = (i, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))

        if same:
            # Horizontal tiles meet the side neighbor at its outer strip.
            for di, nk in ((-1, K - 1), (1, 0)):
                node = (i + di, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            # Across top/bottom, the edge tile touches all strips.
            if k in (0, K - 1):
                for dj in (-1, 1):
                    ni, nj = i, j + dj
                    choices = {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
        else:
            # Vertical tiles meet the top/bottom neighbor at its outer strip.
            for dj, nk in ((-1, K - 1), (1, 0)):
                node = (i, j + dj, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            # Across left/right, the edge tile touches all strips.
            if k in (0, K - 1):
                for di in (-1, 1):
                    ni, nj = i + di, j
                    choices = {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
    return block_bound

from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Determine the optimal winner in the card game."""
    initial_takahashi = tuple(sorted(takahashi_cards))
    initial_aoki = tuple(sorted(aoki_cards))
    initial_table = tuple(sorted(table_cards))
    active = set()

    @lru_cache(maxsize=None)
    def winning(takahashi: Tuple[int, ...], aoki: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        hand = takahashi if turn == 0 else aoki
        if not hand:
            return False

        state = (takahashi, aoki, table, turn)
        active.add(state)
        try:
            for played_index, played in enumerate(hand):
                hand_without_play = hand[:played_index] + hand[played_index + 1:]
                base_table = tuple(sorted(table + (played,)))
                played_table_index = base_table.index(played)

                successors = [(hand_without_play, aoki, base_table, 1)] if turn == 0 else [(takahashi, hand_without_play, base_table, 0)]
                for take_index, taken in enumerate(base_table):
                    if taken > played:
                        break
                    if take_index == played_table_index:
                        continue
                    next_hand = tuple(sorted(hand_without_play + (taken,)))
                    next_table = base_table[:take_index] + base_table[take_index + 1:]
                    successors.append((next_hand, aoki, next_table, 1) if turn == 0 else (takahashi, next_hand, next_table, 0))

                for successor in successors:
                    if successor in active:
                        continue
                    if not winning(*successor):
                        return True
            return False
        finally:
            active.remove(state)

    return "Takahashi" if winning(initial_takahashi, initial_aoki, initial_table, 0) else "Aoki"

from typing import List
from functools import lru_cache


def determine_winner(n: int, a: List[int]) -> str:
    """Given the decrement-and-mark game in which the last move wins."""
    # The game state only needs each remaining pile and the set already marked.
    # Exact search is practical for small games; larger piles are handled by
    # the same recurrence with memoization.
    @lru_cache(None)
    def winning(rem: tuple[int, ...], marked: int) -> bool:
        if marked == (1 << n) - 1:
            return False
        for i, count in enumerate(rem):
            if count == 0:
                continue
            nxt = list(rem)
            nxt[i] -= 1
            next_marked = marked | (1 << i)
            if next_marked == (1 << n) - 1 or not winning(tuple(nxt), next_marked):
                return True
        return False

    return "Fennec" if winning(tuple(a), 0) else "Snuke"

