            if k in (0, K - 1):
                for dj in (-1, 1):
                    ni, nj = i, j + dj
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
        else:
            # Every vertical strip meets the outer horizontal strip above/below.
            for dj, nk in ((-1, K - 1), (1, 0)):
                node = (i, j + dj, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            # Only an outer vertical strip reaches the side; it meets all
            # horizontal strips along that side.
            if k in (0, K - 1):
                for di in (-1, 1):
                    ni, nj = i + di, j
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
    return block_bound

