from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s.count("B") != t.count("B"):
        return -1
    start = (s + "__").encode("ascii")
    goal = (t + "__").encode("ascii")
    if start == goal:
        return 0
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        state, distance = queue.popleft()
        a = state.index(95)
        b = state.index(95, a + 1)
        for i in range(len(state) - 1):
            x, y = state[i], state[i + 1]
            if x == 95 or y == 95:
                continue
            for u, v in ((x, y), (y, x)):
                nxt = bytearray(state)
                nxt[a], nxt[b] = u, v
                nxt[i] = nxt[i + 1] = 95
                nxt = bytes(nxt)
                if nxt == goal:
                    return distance + 1
                if nxt not in visited:
                    visited.add(nxt)
                    queue.append((nxt, distance + 1))
    return -1

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending with s whose digits
    are all at most limit.
    """
    if not s or any(ch < "0" or ch > "9" for ch in s):
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    suffix_length = len(s)
    suffix_scale = 10 ** suffix_length

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count length-digit decimal prefixes (no leading zero) <= bound,
        with each digit at most limit.
        """
        if bound < 0:
            return 0
        text = str(bound)
        if len(text) < length:
            return 0
        if len(text) > length:
            return (limit * (limit + 1) ** (length - 1))
        total = 0
        for i, char in enumerate(text):
            digit = ord(char) - ord("0")
            low = 1 if i == 0 else 0
            remaining = length - i - 1
            choices_after = (limit + 1) ** remaining
            allowed_below = max(0, min(limit, digit - 1) - low + 1)
            total += allowed_below * choices_after
            if digit < low or digit > limit:
                return total
        return total + 1

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        max_length = len(str(bound))
        answer = 0
        for total_length in range(suffix_length, max_length + 1):
            prefix_length = total_length - suffix_length
            if prefix_length == 0:
                # The suffix itself is a representation only if it has no
                # leading zero and denotes a positive integer.
                if s[0] != "0" and suffix_value <= bound:
                    answer += 1
            else:
                max_prefix = (bound - suffix_value) // suffix_scale
                answer += count_prefixes_at_most(max_prefix, prefix_length)
        return answer

    return count_up_to(finish) - count_up_to(start - 1)

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start = tile(S_x, S_y)
    target = tile(T_x, T_y)
    if start == target:
        return 0

    # For long journeys, each block-boundary crossing changes to the
    # perpendicular strip tiling. The strip index costs are confined to the
    # endpoints; the Manhattan distance in blocks is the bulk path length.
    block_dist = abs(ti - si) + abs(tj - sj)
    if block_dist > 500:
        return block_dist

    def neighbors(node):
        i, j, k = node
        horizontal = (i - j) % 2 == 0
        out = []
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                out.append((i, j, nk))
        if horizontal:
            out.append((i + 1, j, 0))
            out.append((i - 1, j, K - 1))
            if k == K - 1:
                out.extend((i, j + 1, m) for m in range(K))
            if k == 0:
                out.extend((i, j - 1, m) for m in range(K))
        else:
            out.append((i, j + 1, 0))
            out.append((i, j - 1, K - 1))
            if k == K - 1:
                out.extend((i + 1, j, m) for m in range(K))
            if k == 0:
                out.extend((i - 1, j, m) for m in range(K))
        return out

    q = deque([(start, 0)])
    seen = {start}
    while q:
        node, dist = q.popleft()
        for nxt in neighbors(node):
            if nxt == target:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, dist + 1))
    raise RuntimeError("tile graph is disconnected")

