def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements whose resulting string has at least k good substrings.

    A substring is good exactly when the three character counts have equal
    parity: deleting equal pairs preserves each parity, and deleting an ABC
    triple toggles all three parities together.
    """
    mod = 998244353
    if k <= 0:
        return pow(3, s.count("?"), mod)
    if k > n * (n + 1) // 2:
        return 0

    # Prefix parity vectors are considered modulo the all-ones vector, since
    # adding/removing one ABC triple changes all three coordinates together.
    # Represent the resulting four classes by two bits (A xor C, B xor C).
    # Each letter advances to a different nonzero class: A=1, B=2, C=3.
    moves = {"A": 1, "B": 2, "C": 3}
    # Key: counts at prefix class 0, 1, 2, followed by the current class.
    # The count at class 3 is inferred from the number of prefixes seen.
    dp = {(1, 0, 0, 0): 1}

    for ch in s:
        choices = (1, 2, 3) if ch == "?" else (moves[ch],)
        next_dp = {}
        for (c0, c1, c2, state), ways in dp.items():
            for move in choices:
                nxt = state ^ move
                if nxt == 0:
                    key = (c0 + 1, c1, c2, nxt)
                elif nxt == 1:
                    key = (c0, c1 + 1, c2, nxt)
                elif nxt == 2:
                    key = (c0, c1, c2 + 1, nxt)
                else:
                    key = (c0, c1, c2, nxt)
                next_dp[key] = (next_dp.get(key, 0) + ways) % mod
        dp = next_dp

    total_prefixes = n + 1
    answer = 0
    for (c0, c1, c2, _state), ways in dp.items():
        c3 = total_prefixes - c0 - c1 - c2
        good = (c0 * (c0 - 1) + c1 * (c1 - 1) +
                c2 * (c2 - 1) + c3 * (c3 - 1)) // 2
        if good >= k:
            answer = (answer + ways) % mod
    return answer

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start, target = tile(S_x, S_y), tile(T_x, T_y)
    if start == target:
        return 0
    block_dist = abs(ti - si) + abs(tj - sj)
    if block_dist > 500:
        return block_dist

    useful_indices = {0, K - 1, start[2], target[2]}

    def neighbors(node):
        i, j, k = node
        horizontal = (i - j) % 2 == 0
        out = []
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                out.append((i, j, nk))
        if horizontal:
            out.extend(((i + 1, j, 0), (i - 1, j, K - 1)))
            if k == K - 1:
                out.extend((i, j + 1, m) for m in useful_indices)
            if k == 0:
                out.extend((i, j - 1, m) for m in useful_indices)
        else:
            out.extend(((i, j + 1, 0), (i, j - 1, K - 1)))
            if k == K - 1:
                out.extend((i + 1, j, m) for m in useful_indices)
            if k == 0:
                out.extend((i - 1, j, m) for m in useful_indices)
        return out

    q = deque([(start, 0)])
    seen = {start}
    while q:
        node, dist = q.popleft()
        for nxt in neighbors(node):
            if nxt == target:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, dist + 1))
    raise RuntimeError("tile graph is disconnected")

