def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """ Calculate twice the area of black-painted regions inside a rectangle on AtCoder's wallpaper pattern.

    The wallpaper pattern is defined as follows:
    - The plane is divided by lines: x = n (integer n), y = n (even n), and x + y = n (even n)
    - Adjacent regions along these lines have different colors (black or white)
    - The region containing (0.5, 0.5) is black

    Given a rectangle with bottom-left vertex at (A, B) and top-right vertex at (C, D),
    calculate the area of black regions inside it and return twice that area.
    """
    from fractions import Fraction

    def count_multiples(lo, hi, step):
        if lo > hi:
            lo, hi = hi, lo
        first = lo // step + 1
        last = -((-hi) // step) - 1
        return max(0, last - first + 1)

    def is_black(x, y):
        # Follow a generic path from (1/2,1/2), first vertically and then horizontally.
        crossings = count_multiples(Fraction(1, 2), y, 2)
        crossings += count_multiples(Fraction(1), y + Fraction(1, 2), 2)
        crossings += count_multiples(Fraction(1, 2), x, 1)
        crossings += count_multiples(Fraction(1, 2) + y, x + y, 2)
        return crossings % 2 == 0

    def tile_value(n, m):
        if (n + m) % 2:
            return int(is_black(Fraction(3*n+1, 3), Fraction(3*m+1, 3))) + int(
                is_black(Fraction(3*n+2, 3), Fraction(3*m+2, 3))
            )
        return 2 * int(is_black(Fraction(2*n+1, 2), Fraction(2*m+1, 2)))

    period = [[tile_value(i, j) for i in range(4)] for j in range(4)]
    pref = [[0] * 5 for _ in range(5)]
    for j in range(4):
        for i in range(4):
            pref[j+1][i+1] = period[j][i] + pref[j][i+1] + pref[j+1][i] - pref[j][i]

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        return (qx * qy * pref[4][4] + qy * pref[4][rx]
                + qx * pref[ry][4] + pref[ry][rx])

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences of orientations of the graph described."""
    mod = 998244353

    # A relation is a 2 by 2 Boolean matrix. Bit (2 * a + b) means
    # that starting cycle-edge direction state a can reach state b.
    # At vertex i, with incoming edge state a_{i-1} and outgoing state
    # a_i, the cycle contributes 1 + a_{i-1} - a_i. A selected spoke
    # adds either zero or one to d_i.
    #
    # For any fixed sequence of d_i values, there can be several edge
    # orientations witnessing it. Propagating the whole relation from
    # both possible initial states determinizes this two-state automaton,
    # so each distinct sequence is counted exactly once.
    transitions = [[ [0] * 4 for _ in range(16)] for _ in range(2)]
    for has_spoke in range(2):
        for relation in range(16):
            for letter_index in range(4):
                value = letter_index - 1  # d_i - 1
                edge_relation = 0
                for before in range(2):
                    for after in range(2):
                        for spoke_in in range(has_spoke + 1):
                            if before - after + spoke_in == value:
                                edge_relation |= 1 << (2 * before + after)

                composed = 0
                for start in range(2):
                    current = (relation >> (2 * start)) & 3
                    reachable = 0
                    for before in range(2):
                        if current & (1 << before):
                            reachable |= (edge_relation >> (2 * before)) & 3
                    composed |= reachable << (2 * start)
                transitions[has_spoke][relation][letter_index] = composed

    # Begin with the identity relation: either initial state maps to itself.
    dp = [0] * 16
    dp[9] = 1
    for bit in s:
        table = transitions[bit == "1"]
        nxt = [0] * 16
        for relation, ways in enumerate(dp):
            if ways:
                for letter_index in range(4):
                    following = table[relation][letter_index]
                    if following:
                        nxt[following] = (nxt[following] + ways) % mod
        dp = nxt

    # A cyclic orientation exists exactly when the composed relation has
    # at least one diagonal entry, i.e. a starting state can return to itself.
    return sum(ways for relation, ways in enumerate(dp) if relation & 9) % mod

