from functools import lru_cache
from typing import List


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, there is a knight at position (kx, ky) and pawns at
    the given positions. Alice and Bob alternate choosing and capturing one
    remaining pawn using the knight's minimum number of moves. The knight may
    pass over other pawns without capturing them. Alice maximizes the total
    moves and Bob minimizes it, assuming optimal play.
    """
    points = [(kx, ky)] + [tuple(p) for p in positions]
    n = len(positions)

    def knight_distance(a, b):
        dx = abs(a[0] - b[0])
        dy = abs(a[1] - b[1])
        if dx < dy:
            dx, dy = dy, dx
        if dx == 1 and dy == 0:
            return 3
        if dx == 2 and dy == 2:
            return 4
        distance = max((dx + 1) // 2, (dx + dy + 2) // 3)
        if (distance - dx - dy) % 2:
            distance += 1
        return distance

    distances = [[knight_distance(a, b) for b in points] for a in points]

    @lru_cache(maxsize=None)
    def best(mask: int, current: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        if mask.bit_count() % 2 == 0:
            answer = 0
            for i in range(n):
                if not (mask >> i) & 1:
                    answer = max(answer, distances[current][i + 1] +
                                 best(mask | (1 << i), i + 1))
            return answer
        answer = float("inf")
        for i in range(n):
            if not (mask >> i) & 1:
                answer = min(answer, distances[current][i + 1] +
                             best(mask | (1 << i), i + 1))
        return answer

    return best(0, 0)

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    tiles = list(tiles[:n])
    if h <= 0 or w <= 0 or h * w > sum(a * b for a, b in tiles):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]

    # An exact area subset is necessary; reject inputs that cannot supply it.
    possible = {0}
    for area in areas:
        possible |= {value + area for value in possible}
    if h * w not in possible:
        return False

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        remaining = h * w - occupied.bit_count()
        # Check whether some subset of the unused pieces has exactly the
        # remaining area. This also prunes branches that committed a poor choice.
        sums = {0}
        for i, area in enumerate(areas):
            if not (used >> i) & 1:
                sums |= {value + area for value in tuple(sums)}
        if remaining not in sums:
            return False

        missing = full ^ occupied
        pos = (missing & -missing).bit_length() - 1
        row, col = divmod(pos, w)

        seen = set()
        # Larger pieces first tends to reduce the search tree. The same shape
        # need only be tried once at a given state.
        order = sorted(
            (i for i in range(len(tiles)) if not (used >> i) & 1),
            key=lambda i: areas[i],
            reverse=True,
        )
        for i in order:
            a, b = tiles[i]
            orientations = {(a, b), (b, a)}
            for rh, rw in orientations:
                if (rh, rw) in seen:
                    continue
                seen.add((rh, rw))
                if row + rh > h or col + rw > w or rh * rw > remaining:
                    continue
                row_bits = ((1 << rw) - 1) << col
                placement = 0
                for rr in range(row, row + rh):
                    placement |= row_bits << (rr * w)
                if occupied & placement == 0:
                    if search(occupied | placement, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

from bisect import bisect_right
from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=1)
def _non_square_perfect_powers():
    """Return sorted perfect powers <= 10**18 that are not squares."""
    limit = 10**18
    powers = set()

    # Any nonsquare perfect power has a representation with exponent >= 3.
    # Enumerating every exponent catches all such values; the set removes
    # duplicates such as 2**6 == 4**3.
    for exponent in range(3, 60):
        low, high = 1, 1
        while pow(high, exponent) <= limit:
            high *= 2
        while low + 1 < high:
            middle = (low + high) // 2
            if pow(middle, exponent) <= limit:
                low = middle
            else:
                high = middle
        base_limit = low

        for base in range(2, base_limit + 1):
            value = pow(base, exponent)
            if isqrt(value) ** 2 != value:
                powers.add(value)

    return sorted(powers)


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] representable as a**b, b >= 2."""
    return isqrt(n) + bisect_right(_non_square_perfect_powers(), n)

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    mod = 998244353

    # Transfer across the shorter dimension to keep the row-state count small.
    if W <= H:
        rows = [tuple(ch for ch in row) for row in grid]
    else:
        rows = [tuple(grid[r][c] for r in range(H)) for c in range(W)]
    height = len(rows)
    width = len(rows[0])

    # Enumerate horizontally proper color sequences.  Encode colors as 0, 1, 2.
    states = []
    def gen(prefix):
        if len(prefix) == width:
            states.append(tuple(prefix))
            return
        allowed = range(3)
        if prefix:
            allowed = (c for c in range(3) if c != prefix[-1])
        for c in allowed:
            prefix.append(c)
            gen(prefix)
            prefix.pop()
    gen([])

    valid_by_row = []
    for row in rows:
        allowed = []
        for state in states:
            if all(ch == '?' or int(ch) - 1 == c for ch, c in zip(row, state)):
                allowed.append(state)
        valid_by_row.append(allowed)
        if not allowed:
            return 0

    # For each row transition, retain only vertically compatible states.
    dp = {state: 1 for state in valid_by_row[0]}
    for allowed in valid_by_row[1:]:
        ndp = {}
        # Each state has exactly two possible different colors in every column.
        for prev, ways in dp.items():
            for cur in allowed:
                if all(a != b for a, b in zip(prev, cur)):
                    ndp[cur] = (ndp.get(cur, 0) + ways) % mod
        dp = ndp
        if not dp:
            return 0
    return sum(dp.values()) % mod

