def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area inside a rectangle for the periodic wallpaper."""
    from fractions import Fraction

    def count_multiples(lo, hi, step):
        if lo > hi:
            lo, hi = hi, lo
        first = lo // step + 1
        last = -((-hi) // step) - 1
        return max(0, last - first + 1)

    def is_black(x, y):
        # Move horizontally from (1/2,1/2), then vertically to the point.
        crossings = count_multiples(Fraction(1, 2), x, 1)
        crossings += count_multiples(Fraction(1), x + Fraction(1, 2), 2)
        crossings += count_multiples(Fraction(1, 2), y, 2)
        crossings += count_multiples(x + Fraction(1, 2), x + y, 2)
        return crossings % 2 == 0

    def tile_value(n, m):
        if (n + m) % 2:
            return int(is_black(Fraction(3*n+1, 3), Fraction(3*m+1, 3))) + int(
                is_black(Fraction(3*n+2, 3), Fraction(3*m+2, 3))
            )
        return 2 * int(is_black(Fraction(2*n+1, 2), Fraction(2*m+1, 2)))

    period = [[tile_value(i, j) for i in range(4)] for j in range(4)]
    pref = [[0] * 5 for _ in range(5)]
    for j in range(4):
        for i in range(4):
            pref[j+1][i+1] = period[j][i] + pref[j][i+1] + pref[j+1][i] - pref[j][i]

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        return (qx * qy * pref[4][4] + qy * pref[4][rx]
                + qx * pref[ry][4] + pref[ry][rx])

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

