from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given N sections to monitor on a conveyor belt, find the minimum cost to monitor all sections.

    Each section must be covered by sensors whose total lengths are at least its length.
    The sensor count limits apply across all sections.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # dp[x] is the least number of type 2 sensors needed after the processed
    # sections when exactly x type 1 sensors have been used.
    dp = [None] * (k1 + 1)
    dp[0] = 0

    for length in sections[:n]:
        max_x = min(k1, (length + l1 - 1) // l1)
        choices = []
        for x in range(max_x + 1):
            remaining = length - x * l1
            y = 0 if remaining <= 0 else (remaining + l2 - 1) // l2
            if y <= k2:
                choices.append((x, y))

        new = [None] * (k1 + 1)
        for used_x, used_y in enumerate(dp):
            if used_y is None:
                continue
            for add_x, add_y in choices:
                total_x = used_x + add_x
                total_y = used_y + add_y
                if total_x <= k1 and total_y <= k2:
                    old = new[total_x]
                    if old is None or total_y < old:
                        new[total_x] = total_y
        dp = new

    best = None
    for x, y in enumerate(dp):
        if y is not None:
            cost = x * c1 + y * c2
            if best is None or cost < best:
                best = cost
    return -1 if best is None else best

from functools import lru_cache
from typing import List


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, there is a knight at position (kx, ky) and pawns at
    the given positions. Alice and Bob alternate choosing and capturing one
    remaining pawn using the knight's minimum number of moves. The knight may
    pass over other pawns without capturing them. Alice maximizes the total
    moves and Bob minimizes it, assuming optimal play.
    """
    points = [(kx, ky)] + [tuple(p) for p in positions]
    n = len(positions)

    def knight_distance(a, b):
        dx = abs(a[0] - b[0])
        dy = abs(a[1] - b[1])
        if dx < dy:
            dx, dy = dy, dx
        if (dx, dy) == (1, 0):
            return 3
        if (dx, dy) == (1, 1):
            return 4
        if (dx, dy) == (2, 2):
            return 4
        distance = max((dx + 1) // 2, (dx + dy + 2) // 3)
        if (distance - dx - dy) % 2:
            distance += 1
        return distance

    distances = [[knight_distance(a, b) for b in points] for a in points]

    @lru_cache(maxsize=None)
    def best(mask: int, current: int) -> int:
        if mask == (1 << n) - 1:
            return 0
        if mask.bit_count() % 2 == 0:
            answer = 0
            for i in range(n):
                if not (mask >> i) & 1:
                    answer = max(answer, distances[current][i + 1] +
                                 best(mask | (1 << i), i + 1))
            return answer
        answer = float("inf")
        for i in range(n):
            if not (mask >> i) & 1:
                answer = min(answer, distances[current][i + 1] +
                             best(mask | (1 << i), i + 1))
        return answer

    return best(0, 0)

