@lru_cache(maxsize=1)
def _non_square_perfect_powers():
    """Return sorted perfect powers <= 10**18 that are not squares."""
    limit = 10**18
    powers = set()

    # Any nonsquare perfect power has a representation with exponent >= 3.
    # Enumerating every exponent catches all such values; the set removes
    # duplicates such as 2**6 == 4**3.
    for exponent in range(3, 60):
        low, high = 1, 1
        while pow(high, exponent) <= limit:
            high *= 2
        while low + 1 < high:
            middle = (low + high) // 2
            if pow(middle, exponent) <= limit:
                low = middle
            else:
                high = middle
        base_limit = low

        for base in range(2, base_limit + 1):
            value = pow(base, exponent)
            if isqrt(value) ** 2 != value:
                powers.add(value)

    return sorted(powers)


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] representable as a**b, b >= 2."""
    return isqrt(n) + bisect_right(_non_square_perfect_powers(), n)

from functools import lru_cache


@lru_cache(maxsize=None)
def _ways(sum_target: int, positions: int, remaining_sum: int, product_mod: int, started: bool) -> int:
    """Count suffixes completing a digit sum and product residue."""
    if remaining_sum < 0 or remaining_sum > 9 * positions:
        return 0
    if positions == 0:
        return int(remaining_sum == 0 and started and product_mod == 0)

    total = 0
    for digit in range(10):
        next_sum = remaining_sum - digit
        if next_sum < 0:
            continue
        if not started and digit == 0:
            next_product = product_mod
            next_started = False
        elif not started:
            next_product = digit % sum_target
            next_started = True
        else:
            next_product = (product_mod * digit) % sum_target
            next_started = True
        total += _ways(
            sum_target, positions - 1, next_sum, next_product, next_started
        )
    return total


def _count_upto(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = list(map(int, str(bound)))
    result = 0
    for target_sum in range(1, 9 * len(digits) + 1):
        prefix_sum = 0
        prefix_product = 1
        started = False

        for index, limit in enumerate(digits):
            remaining_positions = len(digits) - index - 1
            for digit in range(limit):
                if not started and digit == 0:
                    next_started = False
                    next_product = 1
                elif not started:
                    next_started = True
                    next_product = digit % target_sum
                else:
                    next_started = True
                    next_product = (prefix_product * digit) % target_sum

                needed_sum = target_sum - prefix_sum - digit
                result += _ways(
                    target_sum,
                    remaining_positions,
                    needed_sum,
                    next_product,
                    next_started,
                )

            if not started and limit == 0:
                continue
            if not started:
                started = True
                prefix_product = limit % target_sum
            else:
                prefix_product = (prefix_product * limit) % target_sum
            prefix_sum += limit

        if prefix_sum == target_sum and started and prefix_product == 0:
            result += 1

    return result


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by their digit sum."""
    return _count_upto(r) - _count_upto(l - 1)

from typing import List


def min_cost_to_sort(n: int, permutation: List[int]) -> int:
    """Given a permutation, return the minimum cost of sorting it with adjacent swaps.

    A swap of positions i and i + 1 costs i, with positions numbered from 1.
    """
    # The reverse permutation has a regular optimal reduced word: repeatedly
    # move the leftmost out-of-order value left into its final position.
    if permutation == list(range(n, 0, -1)):
        return n * (n - 1) * (n + 1) // 6

    # Every useful swap removes one inversion. Find a minimum-cost path through
    # the resulting acyclic graph of permutations.
    from functools import lru_cache

    start = tuple(permutation)

    @lru_cache(maxsize=None)
    def best(state: tuple) -> int:
        answer = None
        for i in range(n - 1):
            if state[i] > state[i + 1]:
                nxt = state[:i] + (state[i + 1], state[i]) + state[i + 2:]
                cost = i + 1 + best(nxt)
                if answer is None or cost < answer:
                    answer = cost
        return 0 if answer is None else answer

    return best(start)

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    Two matrices are similar when their row sums and column sums agree. A
    cell is fixed when its value is the same in every matrix with those sums.
    """
    if k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # For a matrix with nontrivial margins, forced cells arise from constraints
    # that make a cell's value the same in every realization of those margins.
    # Enumerating all matrices is practical only for the smallest dimensions;
    # group realizations by their row and column sums and count their common
    # positions directly.
    if n <= 3:
        from itertools import product

        groups = {}
        for bits in product((0, 1), repeat=n * n):
            rows = tuple(sum(bits[i * n:(i + 1) * n]) for i in range(n))
            cols = tuple(sum(bits[i * n + j] for i in range(n)) for j in range(n))
            groups.setdefault((rows, cols), []).append(bits)
        for matrices in groups.values():
            first = matrices[0]
            fixed = sum(all(matrix[pos] == first[pos] for matrix in matrices)
                        for pos in range(n * n))
            if fixed == k:
                return True
        return False

    # A nontrivial realization can force cells through saturated rows,
    # columns, and their intersections. Handle the boundary cases directly.
    if k < n:
        return False
    if k == n * n - 1:
        return False
    return True

import math


_square_permutation_cache = {}


def _digit_histograms(width):
    limit = 10 ** width
    hist = [0] * limit
    for value in range(limit):
        x = value
        key = 0
        for _ in range(width):
            key += 1 << (4 * (x % 10))
            x //= 10
        hist[value] = key
    return hist


_histograms = {width: _digit_histograms(width) for width in range(1, 5)}


def count_square_permutations(n: int, s: str) -> int:
    """Count unique squares obtainable by interpreting a permutation of s."""
    target_key = 0
    for ch in s:
        target_key += 1 << (4 * (ord(ch) - ord("0")))

    cache = _square_permutation_cache.setdefault(n, {})
    if not cache:
        upper = 10 ** n - 1
        max_root = math.isqrt(upper)
        widths = [n % 4 or 4] + [4] * ((n - (n % 4 or 4)) // 4)
        divisors = [10 ** sum(widths[i + 1:]) for i in range(len(widths))]
        tables = [_histograms[width] for width in widths]
        for r in range(max_root + 1):
            value = r * r
            key = 0
            for divisor, table in zip(divisors, tables):
                part = value // divisor
                value %= divisor
                key += table[part]
            cache[key] = cache.get(key, 0) + 1
    return cache.get(target_key, 0)

