def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves on the described plane."""
    def locate(x, y):
        i, j = x // K, y // K
        k = (y - j * K) if (i - j) % 2 == 0 else (x - i * K)
        return i, j, k

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    block_bound = abs(start[0] - goal[0]) + abs(start[1] - goal[1])
    if block_bound > 40:
        return block_bound

    from collections import deque
    q = deque([(start, 0)])
    seen = {start}
    all_strips = range(K) if K <= 200 else None

    while q:
        (i, j, k), dist = q.popleft()
        if (i, j, k) == goal:
            return dist
        same = (i - j) % 2 == 0
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                node = (i, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))

        if same:
            for di, nk in ((-1, K - 1), (1, 0)):
                node = (i + di, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            if k in (0, K - 1):
                for dj in (-1, 1):
                    ni, nj = i, j + dj
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
        else:
            for dj, nk in ((-1, K - 1), (1, 0)):
                node = (i, j + dj, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for di, edge_k in ((-1, 0), (1, K - 1)):
                if k == edge_k:
                    ni, nj = i + di, j
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
    return block_bound

