def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    """Given a valid parenthesis sequence, count strings reachable by repeatedly
    complementing a contiguous valid parenthesis substring.

    Each operation reflects the prefix-balance path on an excursion interval
    across its baseline. This lowers (or leaves) every prefix balance, so the
    reachable paths are exactly the balanced walks lying pointwise below the
    starting path.
    """
    mod = 998244353
    ceiling = [0] * (n + 1)
    for i, ch in enumerate(s, 1):
        ceiling[i] = ceiling[i - 1] + (1 if ch == "(" else -1)

    # dp[h] counts length-i walks ending at height h and staying below
    # the original path at every prefix.
    dp = {0: 1}
    for i in range(1, n + 1):
        cap = ceiling[i]
        nxt = {}
        for h, ways in dp.items():
            up = h + 1
            if up <= cap:
                nxt[up] = (nxt.get(up, 0) + ways) % mod
            down = h - 1
            if down <= cap:
                nxt[down] = (nxt.get(down, 0) + ways) % mod
        dp = nxt
    return dp.get(0, 0)

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent tile moves between the two points."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    start, target = tile(S_x, S_y), tile(T_x, T_y)
    if start == target:
        return 0
    si, sj, _ = start
    ti, tj, _ = target
    if abs(ti - si) + abs(tj - sj) > 500:
        return abs(ti - si) + abs(tj - sj)

    keep = {0, K - 1, start[2], target[2]}

    def neighbors(node):
        i, j, k = node
        horizontal = (i - j) % 2 == 0
        if k > 0:
            yield i, j, k - 1
        if k + 1 < K:
            yield i, j, k + 1
        if horizontal:
            yield i + 1, j, 0
            yield i - 1, j, K - 1
            if k == K - 1:
                for m in keep:
                    yield i, j + 1, m
            if k == 0:
                for m in keep:
                    yield i, j - 1, m
        else:
            yield i, j + 1, 0
            yield i, j - 1, K - 1
            if k == K - 1:
                for m in keep:
                    yield i + 1, j, m
            if k == 0:
                for m in keep:
                    yield i - 1, j, m

    queue = deque([start])
    distance = {start: 0}
    while queue:
        node = queue.popleft()
        d = distance[node]
        for nxt in neighbors(node):
            if nxt == target:
                return d + 1
            if nxt not in distance:
                distance[nxt] = d + 1
                queue.append(nxt)
    raise RuntimeError("tile graph is disconnected")

