from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    pieces = list(tiles[:n])
    if h <= 0 or w <= 0 or len(pieces) != n:
        return False

    areas = [a * b for a, b in pieces]
    subset_areas = [set() for _ in range(1 << n)]
    subset_areas[0] = {0}
    for mask in range(1, 1 << n):
        bit = mask & -mask
        i = bit.bit_length() - 1
        subset_areas[mask] = subset_areas[mask ^ bit] | {
            value + areas[i] for value in subset_areas[mask ^ bit]
        }
    if h * w not in subset_areas[(1 << n) - 1]:
        return False

    full_row = (1 << w) - 1
    empty_rows = (0,) * h

    @lru_cache(maxsize=None)
    def search(occupied: Tuple[int, ...], used: int) -> bool:
        try:
            row = next(r for r in range(h) if occupied[r] != full_row)
        except StopIteration:
            return True

        col = next(c for c in range(w) if not (occupied[row] >> c) & 1)
        remaining_area = sum((full_row ^ row_mask).bit_count() for row_mask in occupied)
        if remaining_area not in subset_areas[((1 << n) - 1) ^ used]:
            return False

        for i, (a, b) in enumerate(pieces):
            if (used >> i) & 1:
                continue
            for height, width in {(a, b), (b, a)}:
                if row + height > h or col + width > w:
                    continue
                span = ((1 << width) - 1) << col
                if any(occupied[r] & span for r in range(row, row + height)):
                    continue
                updated = list(occupied)
                for r in range(row, row + height):
                    updated[r] |= span
                if search(tuple(updated), used | (1 << i)):
                    return True
        return False

    return search(empty_rows, 0)

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent tile moves between the two points."""
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    start, target = tile(S_x, S_y), tile(T_x, T_y)
    if start == target:
        return 0
    si, sj, _ = start
    ti, tj, _ = target
    if abs(ti - si) + abs(tj - sj) > 500:
        return abs(ti - si) + abs(tj - sj)
    keep = {0, 1, K - 2, K - 1, start[2], target[2]}

    def neighbors(node):
        i, j, k = node
        horizontal = (i - j) % 2 == 0
        if k > 0:
            yield i, j, k - 1
        if k + 1 < K:
            yield i, j, k + 1
        if horizontal:
            yield i + 1, j, 0
            yield i - 1, j, K - 1
            if k == K - 1:
                for m in keep:
                    yield i, j + 1, m
            if k == 0:
                for m in keep:
                    yield i, j - 1, m
        else:
            yield i, j + 1, 0
            yield i, j - 1, K - 1
            if k == K - 1:
                for m in keep:
                    yield i + 1, j, m
            if k == 0:
                for m in keep:
                    yield i - 1, j, m

    queue = deque([start])
    distance = {start: 0}
    while queue:
        node = queue.popleft()
        d = distance[node]
        for nxt in neighbors(node):
            if nxt == target:
                return d + 1
            if nxt not in distance:
                distance[nxt] = d + 1
                queue.append(nxt)
    raise RuntimeError("tile graph is disconnected")

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves on the described plane."""
    def locate(x, y):
        i, j = x // K, y // K
        k = (y - j * K) if (i - j) % 2 == 0 else (x - i * K)
        return i, j, k

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    dx, dy = goal[0] - start[0], goal[1] - start[1]
    block_bound = abs(dx) + abs(dy)
    if block_bound > 40:
        # A unit-cost path can alternate horizontal and vertical block
        # crossings. The number of steps on each axis must have the same
        # parity as its net displacement.
        best = None
        lower = max(abs(dx), abs(dy))
        for nx in range(lower, lower + 4):
            for ny in range(max(0, nx - 1), nx + 2):
                if (nx - dx) % 2 == 0 and (ny - dy) % 2 == 0:
                    if best is None or nx + ny < best:
                        best = nx + ny
        return best

    from collections import deque
    q = deque([(start, 0)])
    seen = {start}
    all_strips = range(K) if K <= 200 else None

    while q:
        (i, j, k), dist = q.popleft()
        if (i, j, k) == goal:
            return dist
        same = (i - j) % 2 == 0
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                node = (i, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))

        if same:
            for di, nk in ((-1, K - 1), (1, 0)):
                node = (i + di, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for dj, required_k in ((-1, 0), (1, K - 1)):
                if k == required_k:
                    ni, nj = i, j + dj
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
        else:
            for dj, nk in ((-1, K - 1), (1, 0)):
                node = (i, j + dj, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for di, edge_k in ((-1, 0), (1, K - 1)):
                if k == edge_k:
                    ni, nj = i + di, j
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
    return block_bound

