def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending with s whose digits
    are all at most limit.
    """
    if not s or any(ch < "0" or ch > "9" for ch in s):
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    suffix_length = len(s)
    suffix_scale = 10 ** suffix_length

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count length-digit decimal prefixes (no leading zero) <= bound,
        with each digit at most limit.
        """
        if bound < 0:
            return 0
        text = str(bound)
        if len(text) < length:
            return 0
        if len(text) > length:
            return (limit * (limit + 1) ** (length - 1))
        total = 0
        for i, char in enumerate(text):
            digit = ord(char) - ord("0")
            low = 1 if i == 0 else 0
            remaining = length - i - 1
            choices_after = (limit + 1) ** remaining
            allowed_below = max(0, min(limit, digit - 1) - low + 1)
            total += allowed_below * choices_after
            if digit < low or digit > limit:
                return total
        return total + 1

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        max_length = len(str(bound))
        answer = 0
        for total_length in range(suffix_length, max_length + 1):
            prefix_length = total_length - suffix_length
            if prefix_length == 0:
                # The suffix itself is a representation only if it has no
                # leading zero and denotes a positive integer.
                if s[0] != "0" and suffix_value <= bound:
                    answer += 1
            else:
                max_prefix = (bound - suffix_value) // suffix_scale
                answer += count_prefixes_at_most(max_prefix, prefix_length)
        return answer

    return count_up_to(finish) - count_up_to(start - 1)

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent-tile moves on the described plane."""
    def locate(x, y):
        i, j = x // K, y // K
        k = (y - j * K) if (i - j) % 2 == 0 else (x - i * K)
        return i, j, k

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    dx, dy = goal[0] - start[0], goal[1] - start[1]
    block_bound = abs(dx) + abs(dy)
    if block_bound > 40:
        # A unit-cost path can alternate horizontal and vertical block
        # crossings. The number of steps on each axis must have the same
        # parity as its net displacement.
        best = None
        lower = max(abs(dx), abs(dy))
        for nx in range(lower, lower + 4):
            for ny in range(max(0, nx - 1), nx + 2):
                if (nx - dx) % 2 == 0 and (ny - dy) % 2 == 0:
                    if best is None or nx + ny < best:
                        best = nx + ny
        return best

    from collections import deque
    q = deque([(start, 0)])
    seen = {start}
    all_strips = range(K) if K <= 200 else None

    while q:
        (i, j, k), dist = q.popleft()
        if (i, j, k) == goal:
            return dist
        same = (i - j) % 2 == 0
        for nk in (k - 1, k + 1):
            if 0 <= nk < K:
                node = (i, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))

        if same:
            for di, nk in ((-1, K - 1), (1, 0)):
                node = (i + di, j, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for dj, required_k in ((-1, 0), (1, K - 1)):
                if k == required_k:
                    ni, nj = i, j + dj
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
        else:
            for dj, nk in ((-1, K - 1), (1, 0)):
                node = (i, j + dj, nk)
                if node not in seen:
                    seen.add(node)
                    q.append((node, dist + 1))
            for di, edge_k in ((-1, 0), (1, K - 1)):
                if k == edge_k:
                    ni, nj = i + di, j
                    choices = set(all_strips) if all_strips is not None else {0, K - 1}
                    if (ni, nj) == goal[:2]:
                        choices.add(goal[2])
                    for nk in choices:
                        node = (ni, nj, nk)
                        if node not in seen:
                            seen.add(node)
                            q.append((node, dist + 1))
    return block_bound

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending with s whose digits
    are all at most limit.
    """
    if not s or any(ch < "0" or ch > "9" for ch in s):
        return 0
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)
    suffix_length = len(s)
    suffix_scale = 10 ** suffix_length

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count length-digit decimal prefixes (no leading zero) <= bound,
        with each digit at most limit.
        """
        if bound < 0:
            return 0
        text = str(bound)
        if len(text) < length:
            return 0
        if len(text) > length:
            return (limit * (limit + 1) ** (length - 1))
        total = 0
        for i, char in enumerate(text):
            digit = ord(char) - ord("0")
            low = 1 if i == 0 else 0
            remaining = length - i - 1
            choices_after = (limit + 1) ** remaining
            allowed_below = max(0, min(limit, digit - 1) - low + 1)
            total += allowed_below * choices_after
            if digit < low or digit > limit:
                return total
        return total + 1

    def count_up_to(bound: int) -> int:
        if bound < 1:
            return 0
        max_length = len(str(bound))
        answer = 0
        for total_length in range(suffix_length, max_length + 1):
            prefix_length = total_length - suffix_length
            if prefix_length == 0:
                # The suffix itself is a representation only if it has no
                # leading zero and denotes a positive integer.
                if s[0] != "0" and suffix_value <= bound:
                    answer += 1
            else:
                max_prefix = (bound - suffix_value) // suffix_scale
                answer += count_prefixes_at_most(max_prefix, prefix_length)
        return answer

    return count_up_to(finish) - count_up_to(start - 1)

